"""TopK along the last dim of a 2D fp32 tensor, custom CUDA kernel.

Strategy
--------
Single kernel launch.  Grid = (nb, batch); each block owns a contiguous segment
of one row and computes that segment's *exact* top-k with a block-wide radix
select (4 x 8-bit digits) over elements held in registers.  Each block then
publishes its k fully-sorted (key, index) candidates to global memory.  The
last block of each row (detected with an atomic ticket) merges the nb*k
candidates with the same radix-select routine and writes the final
values (fp32) / indices (int64) sorted descending.

The float->uint32 monotone transform makes the ordering exact and total, so
radix select on the transformed key is equivalent to sorting by value.
"""

import os

import torch
import torch.nn as nn

# ---------------------------------------------------------------------------
# CUDA
# ---------------------------------------------------------------------------

_CPP_SRC = r"""
#include <torch/extension.h>
#include <vector>

void topk_setup(int64_t batch, int64_t n, int64_t k, int64_t nb);
std::vector<torch::Tensor> topk_run(torch::Tensor x);
"""

_CUDA_SRC = r"""#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

#define NT 256

struct Smem {
    unsigned int *hist, *outk, *outi, *wsum, *wmask, *scal;
};

__device__ __forceinline__ unsigned int f2k(float f) {
    unsigned int u = __float_as_uint(f);
    return (u & 0x80000000u) ? ~u : (u | 0x80000000u);
}
__device__ __forceinline__ float k2f(unsigned int key) {
    unsigned int u = (key & 0x80000000u) ? (key & 0x7fffffffu) : ~key;
    return __uint_as_float(u);
}

// Bitonic sort (descending) of the shared arrays key[]/idx[] of size NP (pow2).
__device__ __forceinline__ void bitonic_desc(unsigned int* key, unsigned int* idx, int NP) {
    for (int kk = 2; kk <= NP; kk <<= 1) {
        for (int j = kk >> 1; j > 0; j >>= 1) {
            for (int i = threadIdx.x; i < NP; i += NT) {
                int ixj = i ^ j;
                if (ixj > i) {
                    bool gate = ((i & kk) == 0);
                    unsigned int a = key[i], b = key[ixj];
                    unsigned int ia = idx[i], ib = idx[ixj];
                    bool sw = gate ? (a < b) : (a > b);
                    if (sw) { key[i] = b; key[ixj] = a; idx[i] = ib; idx[ixj] = ia; }
                }
            }
            __syncthreads();
        }
    }
}

// Exact top-k of count elements held in registers as (rkey[i], ridx[i]) for
// element index i*NT + threadIdx.x (i in [0,E)).
// outk[0..k-1] / outi[0..k-1] receive the k selected elements, sorted
// descending by key when do_sort is set.
template <int E>
__device__ __forceinline__ void block_topk(const unsigned int* rkey,
                                           const unsigned int* ridx, int count,
                                           int k, int NP, int do_sort, Smem S) {
    const int t = threadIdx.x;
    const int lane = t & 31;
    const int wid = t >> 5;

    unsigned int prefix = 0u;
    int fixed = 0;
    int rank = k;

    for (int level = 0; level < 4; ++level) {
        // ping-pong histogram buffers: removing the trailing barrier of the
        // previous level is safe because a distinct buffer is used next.
        unsigned int* H = S.hist + (level & 1) * 256;
        for (int i = t; i < 256; i += NT) H[i] = 0u;
        __syncthreads();

        #pragma unroll
        for (int i = 0; i < E; ++i) {
            int j = i * NT + t;
            if (j < count) {
                unsigned int kk = rkey[i];
                bool match = (fixed == 0) || ((kk >> (32 - fixed)) == prefix);
                if (match) atomicAdd(&H[(kk >> (24 - fixed)) & 0xFFu], 1u);
            }
        }
        __syncthreads();

        // inclusive prefix scan of the 256 bins over the whole block
        unsigned int v = H[t];
        #pragma unroll
        for (int o = 1; o < 32; o <<= 1) {
            unsigned int tmp = __shfl_up_sync(0xffffffffu, v, o);
            if (lane >= o) v += tmp;
        }
        if (lane == 31) S.wsum[wid] = v;
        __syncthreads();

        unsigned int off = 0u, total = 0u;
        #pragma unroll
        for (int w = 0; w < 8; ++w) {
            unsigned int ws = S.wsum[w];
            total += ws;
            if (w < wid) off += ws;
        }
        unsigned int inc = off + v;
        unsigned int T0 = total - (unsigned int)rank;
        unsigned int m = __ballot_sync(0xffffffffu, inc > T0);
        if (lane == 0) S.wmask[wid] = m;
        H[t] = total - inc;             // q[d] = #elements with digit > d
        __syncthreads();

        int bw = -1;
        #pragma unroll
        for (int w = 0; w < 8; ++w) { if (bw < 0 && S.wmask[w] != 0u) bw = w; }
        int digit = bw * 32 + (__ffs((int)S.wmask[bw]) - 1);
        unsigned int acc = H[digit];
        // No barrier here: the next level zeroes the *other* buffer.  H is not
        // touched again by this call.

        prefix = (fixed == 0) ? (unsigned int)digit
                              : ((prefix << 8) | (unsigned int)digit);
        fixed += 8;
        rank -= (int)acc;
    }

    // prefix is now the exact k-th largest 32-bit key; `rank` elements equal to
    // it are needed on top of every element strictly greater.
    const unsigned int Kstar = prefix;
    if (t == 0) S.scal[1] = 0u;
    __syncthreads();

    #pragma unroll
    for (int i = 0; i < E; ++i) {
        int j = i * NT + t;
        if (j < count && rkey[i] > Kstar) {
            unsigned int p = atomicAdd(&S.scal[1], 1u);
            S.outk[p] = rkey[i];
            S.outi[p] = ridx[i];
        }
    }
    // The two collect loops write disjoint output slots and share only the
    // atomic counter, so no barrier is needed between them.
    #pragma unroll
    for (int i = 0; i < E; ++i) {
        int j = i * NT + t;
        if (j < count && rkey[i] == Kstar) {
            unsigned int p = atomicAdd(&S.scal[1], 1u);
            if ((int)p < k) { S.outk[p] = rkey[i]; S.outi[p] = ridx[i]; }
        }
    }
    __syncthreads();

    if (do_sort) {
        for (int i = k + t; i < NP; i += NT) { S.outk[i] = 0u; S.outi[i] = 0u; }
        __syncthreads();
        bitonic_desc(S.outk, S.outi, NP);
    }
}

template <int E>
__device__ __forceinline__ void load_topk_f(const float* __restrict__ x, int start,
                                            int cnt, long long rbase, int k, int NP,
                                            int do_sort, Smem S) {
    unsigned int rkey[E], ridx[E];
    #pragma unroll
    for (int i = 0; i < E; ++i) {
        int j = i * NT + threadIdx.x;
        if (j < cnt) {
            rkey[i] = f2k(x[rbase + start + j]);
            ridx[i] = (unsigned int)(start + j);
        } else { rkey[i] = 0u; ridx[i] = 0u; }
    }
    block_topk<E>(rkey, ridx, cnt, k, NP, do_sort, S);
}

template <int E>
__device__ __forceinline__ void load_topk_c(const unsigned int* __restrict__ ck,
                                            const unsigned int* __restrict__ ci,
                                            long long mb, int cnt, int k, int NP,
                                            int do_sort, Smem S) {
    unsigned int rkey[E], ridx[E];
    #pragma unroll
    for (int i = 0; i < E; ++i) {
        int j = i * NT + threadIdx.x;
        if (j < cnt) { rkey[i] = ck[mb + j]; ridx[i] = ci[mb + j]; }
        else { rkey[i] = 0u; ridx[i] = 0u; }
    }
    block_topk<E>(rkey, ridx, cnt, k, NP, do_sort, S);
}

#define TOPK_DISPATCH(EV, CALL)          \
    switch (EV) {                        \
        case 2:  CALL(2);  break;        \
        case 4:  CALL(4);  break;        \
        case 8:  CALL(8);  break;        \
        default: CALL(16); break;        \
    }

__global__ void __launch_bounds__(NT) topk_kernel(
        const float* __restrict__ x, int n, int k, int nb, int seg, int e1, int e2,
        unsigned int* __restrict__ cand_key,
        unsigned int* __restrict__ cand_idx, int* __restrict__ ctr,
        float* __restrict__ out_val, long long* __restrict__ out_idx) {
    extern __shared__ unsigned int smem[];
    int NP = 1; while (NP < k) NP <<= 1;
    Smem S;
    S.hist = smem;
    S.outk = smem + 512;
    S.outi = S.outk + NP;
    S.wsum = S.outi + NP;
    S.wmask = S.wsum + 8;
    S.scal = S.wmask + 8;

    const int row = blockIdx.y;
    const int b = blockIdx.x;
    const int t = threadIdx.x;

    const int start = b * seg;
    const int cnt = min(seg, n - start);
    const long long rbase = (long long)row * (long long)n;

    if (cnt > 0) {
        #define CALL_F(EE) load_topk_f<EE>(x, start, cnt, rbase, k, NP, 0, S)
        TOPK_DISPATCH(e1, CALL_F)
        #undef CALL_F
        long long cb = ((long long)row * nb + b) * (long long)k;
        for (int i = t; i < k; i += NT) {
            cand_key[cb + i] = S.outk[i];
            cand_idx[cb + i] = S.outi[i];
        }
    }

    __threadfence();
    __syncthreads();

    __shared__ int is_last;
    if (t == 0) {
        int ticket = atomicAdd(&ctr[row], 1);
        is_last = (ticket == nb - 1);
    }
    __syncthreads();
    if (!is_last) return;

    // ---- merge nb*k candidates ----
    const int mc = nb * k;
    const long long mb = (long long)row * (long long)mc;
    #define CALL_C(EE) load_topk_c<EE>(cand_key, cand_idx, mb, mc, k, NP, 1, S)
    TOPK_DISPATCH(e2, CALL_C)
    #undef CALL_C
    for (int i = t; i < k; i += NT) {
        out_val[(long long)row * k + i] = k2f(S.outk[i]);
        out_idx[(long long)row * k + i] = (long long)S.outi[i];
    }
    if (t == 0) ctr[row] = 0;
}

// ---------------------------------------------------------------------------
// Host side.  Persistent buffers live in leaked heap objects so nothing is
// allocated (and no static destructor runs) per call.
// ---------------------------------------------------------------------------
static torch::Tensor* g_ckey = nullptr;
static torch::Tensor* g_cidx = nullptr;
static torch::Tensor* g_ctr = nullptr;
static torch::Tensor* g_vals = nullptr;
static torch::Tensor* g_inds = nullptr;
static int64_t g_k = 0, g_nb = 0;

void topk_setup(int64_t batch, int64_t n, int64_t k, int64_t nb) {
    auto i32 = torch::TensorOptions().dtype(torch::kInt32).device(torch::kCUDA);
    int64_t ncand = batch * nb * k;
    delete g_ckey; delete g_cidx; delete g_ctr; delete g_vals; delete g_inds;
    g_ckey = new torch::Tensor(torch::empty({ncand}, i32));
    g_cidx = new torch::Tensor(torch::empty({ncand}, i32));
    g_ctr = new torch::Tensor(torch::zeros({batch}, i32));
    g_vals = new torch::Tensor(torch::empty({batch, k}, i32.dtype(torch::kFloat32)));
    g_inds = new torch::Tensor(torch::empty({batch, k}, i32.dtype(torch::kInt64)));
    g_k = k;
    g_nb = nb;
}

std::vector<torch::Tensor> topk_run(torch::Tensor x) {
    if (!x.is_contiguous()) x = x.contiguous();
    const int64_t batch = x.size(0);
    const int64_t n = x.size(1);
    const int k = (int)g_k;
    const int nb = (int)g_nb;
    const int seg = (int)((n + nb - 1) / nb);

    int NP = 1; while (NP < k) NP <<= 1;
    size_t shmem = sizeof(unsigned int) * (size_t)(512 + 2 * NP + 8 + 8 + 8);

    int e1 = 2; while (e1 * NT < seg) e1 <<= 1;
    int e2 = 2; while (e2 * NT < nb * k) e2 <<= 1;

    dim3 grid((unsigned)nb, (unsigned)batch);
    topk_kernel<<<grid, NT, shmem>>>(
        x.data_ptr<float>(), (int)n, k, nb, seg, e1, e2,
        reinterpret_cast<unsigned int*>(g_ckey->data_ptr<int>()),
        reinterpret_cast<unsigned int*>(g_cidx->data_ptr<int>()),
        g_ctr->data_ptr<int>(),
        g_vals->data_ptr<float>(),
        reinterpret_cast<long long*>(g_inds->data_ptr<int64_t>()));

    return {*g_vals, *g_inds};
}
"""


# ---------------------------------------------------------------------------
# Python side
# ---------------------------------------------------------------------------

_NT = 256
_EMAX = 16
_MAXSEG = _NT * _EMAX


def _choose_nb(n, k, batch):
    """Pick blocks-per-row so that seg <= 4096, nb*k <= 4096 and every block
    owns at least k elements."""
    nb_max = max(1, _MAXSEG // max(1, k))
    nb_max = min(nb_max, max(1, 2048 // max(1, k)))
    nb_min = max(1, (n + _MAXSEG - 1) // _MAXSEG)
    target = max(1, (512 + batch - 1) // batch)
    nb = min(max(nb_min, target), nb_max)
    nb = max(1, nb)
    while nb > 1:
        seg = (n + nb - 1) // nb
        cnt_min = n - (nb - 1) * seg
        if seg >= k and cnt_min >= k and seg <= _MAXSEG and nb * k <= _MAXSEG:
            break
        nb -= 1
    seg = (n + nb - 1) // nb
    if seg > _MAXSEG or seg < k or nb * k > _MAXSEG:
        nb = max(1, (n + _MAXSEG - 1) // _MAXSEG)
    return nb


_ext = None
_diag_done = [False]


def _load_ext():
    global _ext
    if _ext is None:
        from torch.utils.cpp_extension import load_inline
        _ext = load_inline(
            name="topk_radix_ext",
            cpp_sources=_CPP_SRC,
            cuda_sources=_CUDA_SRC,
            functions=["topk_setup", "topk_run"],
            extra_cuda_cflags=["-O3"],
            verbose=False,
        )
    return _ext


def _diag(run, x):
    import time
    for _ in range(5):
        run(x)
    torch.cuda.synchronize()
    t0 = time.perf_counter()
    for _ in range(1000):
        run(x)
    t1 = time.perf_counter()
    torch.cuda.synchronize()
    wall = (t1 - t0) * 1e6 / 1000.0
    s = torch.cuda.Event(enable_timing=True)
    e = torch.cuda.Event(enable_timing=True)
    s.record()
    for _ in range(500):
        run(x)
    e.record()
    torch.cuda.synchronize()
    bb = s.elapsed_time(e) * 1000.0 / 500.0
    for _ in range(5):
        x.sum()
    s.record()
    for _ in range(200):
        x.sum()
    e.record()
    torch.cuda.synchronize()
    sm = s.elapsed_time(e) * 1000.0 / 200.0
    print("KDIAG wall_us=%.2f kernel_us=%.2f sum_us=%.2f" % (wall, bb, sm),
          flush=True)


class Model(nn.Module):
    """Top-k over the last dim of a 2D fp32 tensor (see reference.py)."""

    def __init__(self, batch: int, n: int, k: int):
        super().__init__()
        self.batch, self.n, self.k = batch, n, k
        self.register_buffer("_dummy", torch.zeros(1))
        self._nb = _choose_nb(n, k, batch)
        self._run = self._first

    def _first(self, x):
        ext = _load_ext()
        ext.topk_setup(self.batch, self.n, self.k, self._nb)
        self._run = ext.topk_run
        if os.environ.get("TOPK_DIAG", "0") == "1" and not _diag_done[0]:
            _diag_done[0] = True
            try:
                _diag(self._run, x)
            except Exception:
                pass
        return self._run(x)

    def forward(self, x):
        return self._run(x)

    def __call__(self, x):
        return self._run(x)


